questionvariables.text:
/* Part (a) */

fact1:rand_with_step(2,6,1);
fact2:rand_with_step(fact1+1,9,1);

segDE:fact1*fact2;
segAE:fact1*(fact2-1);
segAB:fact2*(fact1+3)-segAE;

tans1:(segAE*(segAE+segAB)/segDE)-segDE;

/* Part (b) */

rad:rand_with_step(2*ceiling(segAB/2),2*segAB,2)/2;

tans2:round(acos(tans1/(2*rad))*360/%pi);

feedbackvariables.text:
/* Node 1: Correct answer */
/* Node 2: Worked solution */

/* Node 3: Correctly finds CE but does not subtract DE (2) */

/* Node 4: Uses BA and CD in place of BE and CE (1) */
node4_test: if abs(ans1-(segAE*segAB/segDE))<=0.1 then 1 else 0;

/* Node 5: Uses incorrect version of chord rule (1) */
node5_test: if abs(ans1-((segDE*(segAE+segAB)/segAE)-segDE))<=0.1 or abs(ans1-((segAE*segDE/(segAE+segAB))-segDE))<=0.1 then 1 else 0;

/* Node 6: Uses incorrect version of chord rule and BA,CD in place of BE,CE (feedback) */
node6_test: if abs(ans1-(segDE*segAB/segAE))<=0.1 or abs(ans1-(segAE*segDE/segAB))<=0.1 then 1 else 0;

/* Node 1: Correct answer */
/* Node 2: Worked solution */
/* Node 3: ECF (4) */
ecf2: round(acos(ans1/(2*rad))*360/%pi);

/* Node 4: Rounds incorrectly (3) */
node4_test: if abs(ans2-tans2)<=0.1 then 1 else 0;

/* Node 5: Rounds incorrectly (3) */
node5_test: if abs(ans2-ecf2)<=0.1 then 1 else 0;

/* Node 6: Uses incorrect trigonometry but correctly doubles angle CDB (2) */
node6_test: if is(ans2=round(acos((2*rad)/ans1)*360/%pi)) or is(ans2=round(asin(ans1/(2*rad))*360/%pi)) or is(ans2=round(asin((2*rad)/ans1)*360/%pi)) or is(ans2=round(atan(ans1/(2*rad))*360/%pi)) or is(ans2=round(atan((2*rad)/ans1)*360/%pi)) then 1 else 0;

/* Node 7: Uses incorrect circle theorem but correctly finds CDB (2) */
node7_test: if is(ans2=round(acos(ans1/(2*rad))*180/%pi)) or is(ans2=round(180-acos(ans1/(2*rad))*180/%pi)) or is(ans2=round(90+acos(ans1/(2*rad))*180/%pi)) then 1 else 0;

/* Node 8: Node 6 error with incorrect rounding (1) */
node8_test: if abs(ans2-acos((2*rad)/ans1)*360/%pi)<=1 or abs(ans2-asin(ans1/(2*rad))*360/%pi)<=1 or abs(ans2-asin((2*rad)/ans1)*360/%pi)<=1 or abs(ans2-atan(ans1/(2*rad))*360/%pi)<=1 or abs(ans2-atan((2*rad)/ans1)*360/%pi)<=1 then 1 else 0;

/* Node 9: Node 7 error with incorrect rounding (1) */
node9_test: if abs(ans2-acos(ans1/(2*rad))*180/%pi)<=1 or abs(ans2-180+acos(ans1/(2*rad))*180/%pi)<=1 or abs(ans1-90-acos(ans2/(2*rad))*180/%pi)<=1 then 1 else 0;
